from taf.rfrl.l3_call.delta.delta import ClassicalDeltaOperator, CloudDeltaOperator
from taf.rfrl.l3_call.delta.exceptions import InvalidRan


class DeltaOperatorFactory:
    """
    Creates ClassicalDeltaOperator or CloudDeltaOperator instances
    """

    @staticmethod
    def create_delta_operator(ran, connection_alias, delta_id):
        """
        Creates and returns an instance of the appropriate delta operator class
        based on the given RAN.

        :param ran: RAN type: cloud/classical
        :type ran: str
        :param connection_alias: The connection alias.
        :type connection_alias: str
        :param delta_id: The delta ID.
        :type delta_id: str
        :return: The delta operator instance.
        :rtype: ClassicalDeltaOperator or CloudDeltaOperator
        """
        if ran == "cloud":
            return CloudDeltaOperator(connection_alias=connection_alias,
                                      delta_id=delta_id)
        elif ran == "classical":
            return ClassicalDeltaOperator(connection_alias=connection_alias,
                                          delta_id=delta_id)
        else:
            raise InvalidRan("RAN must be either cloud or classical!")
